// Decide what the tracking screen shows for a permission response.
// Returns one of: 'wait' | 'proceed' | 'ask' | 'open-settings'
function permissionAction(response) {
  if (response.status === 'granted') return 'proceed';
  return 'ask';
}

console.log(permissionAction({ status: 'denied', granted: false, canAskAgain: false, expires: 'never' }));

