function permissionAction(response) {
  if (!response) return 'wait';
  if (response.granted) return 'proceed';
  if (response.status === 'undetermined') return 'ask';
  return response.canAskAgain ? 'ask' : 'open-settings';
}

console.log(permissionAction({ status: 'denied', granted: false, canAskAgain: false, expires: 'never' }));
